import * as dns from 'node:dns';
import * as wt from 'node:worker_threads';
import * as http from 'node:http';
import * as https from 'node:https';
import * as net from 'node:net';
import * as url from 'node:url';
function main(): void {
  function t(n: string, C: any, a?: any, b?: any, c?: any) { try { const o = new C(a, b, c); console.log(n, 'new ok', typeof o); } catch (e: any) { console.log(n, 'THROW', e && e.message); } }
  t('dns.Resolver', dns.Resolver);
  t('wt.BroadcastChannel', wt.BroadcastChannel, 'x');
  t('http.Agent', http.Agent);
  t('http.ClientRequest', http.ClientRequest, 'http://127.0.0.1:1/');
  t('https.Agent', https.Agent);
  t('net.Stream', net.Stream);
  t('url.Url', url.Url);
  process.exit(0);
}
